-- ZB-2: immutable signing-authority snapshot per prepared-contract revision.
-- This migration is versioned only; it is not executed by this task.

create table public.prepared_contract_signatur_snapshot_person (
  id bigint generated by default as identity primary key,
  kommunikationsvorgang_id bigint not null references public.kommunikationsvorgang(id) on delete restrict,
  signatur_revision integer not null check (signatur_revision >= 1),
  mitglied_id bigint not null references public.mitglied(id) on delete restrict,
  unterzeichner_name_snapshot text not null check (nullif(btrim(unterzeichner_name_snapshot),'') is not null),
  snapshot_am timestamptz not null default now(),
  unique(kommunikationsvorgang_id, signatur_revision, mitglied_id)
);

create table public.prepared_contract_signatur_snapshot_quelle (
  id bigint generated by default as identity primary key,
  snapshot_person_id bigint not null references public.prepared_contract_signatur_snapshot_person(id) on delete restrict,
  berechtigungsart text not null check (berechtigungsart in ('direkt','vertretung')),
  vereinsfunktion_id bigint not null references public.vereinsfunktion(id) on delete restrict,
  vereinsfunktion_bezeichnung_snapshot text not null check (nullif(btrim(vereinsfunktion_bezeichnung_snapshot),'') is not null),
  vereinsfunktion_besetzung_id bigint not null references public.vereinsfunktion_besetzung(id) on delete restrict,
  besetzung_gueltig_ab_snapshot date not null,
  besetzung_gueltig_bis_snapshot date,
  vertretung_id bigint references public.vereinsfunktion_vertretung(id) on delete restrict,
  vertretung_gueltig_ab_snapshot date,
  vertretung_gueltig_bis_snapshot date,
  vertretene_vereinsfunktion_id bigint references public.vereinsfunktion(id) on delete restrict,
  vertretene_funktion_bezeichnung_snapshot text,
  vertretene_besetzung_id bigint references public.vereinsfunktion_besetzung(id) on delete restrict,
  vertretene_besetzung_gueltig_ab_snapshot date,
  vertretene_besetzung_gueltig_bis_snapshot date,
  constraint prepared_contract_signatur_snapshot_quelle_vertretung_chk check (
    (berechtigungsart='direkt' and vertretung_id is null and vertretung_gueltig_ab_snapshot is null and vertretung_gueltig_bis_snapshot is null and vertretene_vereinsfunktion_id is null and vertretene_funktion_bezeichnung_snapshot is null and vertretene_besetzung_id is null and vertretene_besetzung_gueltig_ab_snapshot is null and vertretene_besetzung_gueltig_bis_snapshot is null)
    or (berechtigungsart='vertretung' and vertretung_id is not null and vertretung_gueltig_ab_snapshot is not null and vertretene_vereinsfunktion_id is not null and nullif(btrim(vertretene_funktion_bezeichnung_snapshot),'') is not null and vertretene_besetzung_id is not null and vertretene_besetzung_gueltig_ab_snapshot is not null)
  ),
  unique(snapshot_person_id, vereinsfunktion_besetzung_id, vertretung_id)
);

create index ix_prepared_contract_signatur_snapshot_person_vorgang on public.prepared_contract_signatur_snapshot_person(kommunikationsvorgang_id, signatur_revision, mitglied_id);
create index ix_prepared_contract_signatur_snapshot_quelle_person on public.prepared_contract_signatur_snapshot_quelle(snapshot_person_id);

alter table public.prepared_contract_signatur_snapshot_person enable row level security;
alter table public.prepared_contract_signatur_snapshot_quelle enable row level security;
create policy prepared_contract_signatur_snapshot_person_select_admin on public.prepared_contract_signatur_snapshot_person for select to authenticated using (public.is_admin_or_vorstand());
create policy prepared_contract_signatur_snapshot_quelle_select_admin on public.prepared_contract_signatur_snapshot_quelle for select to authenticated using (exists (select 1 from public.prepared_contract_signatur_snapshot_person p where p.id=snapshot_person_id and public.is_admin_or_vorstand()));
revoke all on public.prepared_contract_signatur_snapshot_person, public.prepared_contract_signatur_snapshot_quelle from public, anon, authenticated;
grant select on public.prepared_contract_signatur_snapshot_person, public.prepared_contract_signatur_snapshot_quelle to authenticated;
grant all on public.prepared_contract_signatur_snapshot_person, public.prepared_contract_signatur_snapshot_quelle to service_role;

-- Resolves each signing unit exactly once: an active representation replaces its
-- represented assignment. The caller receives every source; the snapshot creator
-- subsequently deduplicates persons while preserving all their sources.
create or replace function public.resolve_vertragsunterzeichner(p_stichtag date)
returns table(mitglied_id bigint, unterzeichner_name text, berechtigungsart text, vereinsfunktion_id bigint, vereinsfunktion_bezeichnung text, vereinsfunktion_besetzung_id bigint, besetzung_gueltig_ab date, besetzung_gueltig_bis date, vertretung_id bigint, vertretung_gueltig_ab date, vertretung_gueltig_bis date, vertretene_vereinsfunktion_id bigint, vertretene_funktion_bezeichnung text, vertretene_besetzung_id bigint, vertretene_besetzung_gueltig_ab date, vertretene_besetzung_gueltig_bis date)
language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
  if exists (
    select 1 from public.vereinsfunktion_verwendung u join public.vereinsfunktion_besetzung b on b.vereinsfunktion_id=u.vereinsfunktion_id join public.vereinsfunktion_vertretung v on v.vertretene_besetzung_id=b.id
    where u.verwendungszweck='vertragsunterzeichnung' and v.gueltig_ab<=p_stichtag and (v.gueltig_bis is null or v.gueltig_bis>=p_stichtag)
    group by b.id having count(*)>1
  ) then raise exception 'Mehrere gleichzeitig gültige Vertreter für eine Zeichnungsbesetzung' using errcode='23514'; end if;
  return query
  with basis as (
    select b.id,b.mitglied_id,b.gueltig_ab,b.gueltig_bis,f.id funktion_id,f.bezeichnung funktion_bezeichnung
    from public.vereinsfunktion_verwendung u join public.vereinsfunktion f on f.id=u.vereinsfunktion_id and f.aktiv join public.vereinsfunktion_besetzung b on b.vereinsfunktion_id=f.id
    where u.verwendungszweck='vertragsunterzeichnung' and b.gueltig_ab<=p_stichtag and (b.gueltig_bis is null or b.gueltig_bis>=p_stichtag)
  ), rep as (
    select b.*,v.id vertretung_id,v.gueltig_ab vertretung_ab,v.gueltig_bis vertretung_bis,rb.id rb_id,rb.mitglied_id rb_mitglied_id,rb.gueltig_ab rb_ab,rb.gueltig_bis rb_bis,rf.id rf_id,rf.bezeichnung rf_bezeichnung
    from basis b join public.vereinsfunktion_vertretung v on v.vertretene_besetzung_id=b.id and v.gueltig_ab<=p_stichtag and (v.gueltig_bis is null or v.gueltig_bis>=p_stichtag)
      join public.vereinsfunktion_besetzung rb on rb.id=v.vertreter_besetzung_id join public.vereinsfunktion rf on rf.id=rb.vereinsfunktion_id and rf.aktiv
  ), ausuebung as (
    select b.mitglied_id,b.id,b.gueltig_ab,b.gueltig_bis,b.funktion_id,b.funktion_bezeichnung,null::bigint vertretung_id,null::date vertretung_ab,null::date vertretung_bis,null::bigint vertretene_funktion_id,null::text vertretene_funktion_bezeichnung,null::bigint vertretene_besetzung_id,null::date vertretene_ab,null::date vertretene_bis,'direkt'::text art from basis b where not exists(select 1 from rep r where r.id=b.id)
    union all
    select r.rb_mitglied_id,r.rb_id,r.rb_ab,r.rb_bis,r.rf_id,r.rf_bezeichnung,r.vertretung_id,r.vertretung_ab,r.vertretung_bis,r.funktion_id,r.funktion_bezeichnung,r.id,r.gueltig_ab,r.gueltig_bis,'vertretung'::text from rep r
  )
  select a.mitglied_id,coalesce(nullif(btrim(concat_ws(' ',m.vorname,m.name)),''),'Mitglied #'||a.mitglied_id),a.art,a.funktion_id,a.funktion_bezeichnung,a.id,a.gueltig_ab,a.gueltig_bis,a.vertretung_id,a.vertretung_ab,a.vertretung_bis,a.vertretene_funktion_id,a.vertretene_funktion_bezeichnung,a.vertretene_besetzung_id,a.vertretene_ab,a.vertretene_bis from ausuebung a join public.mitglied m on m.id=a.mitglied_id;
end; $$;

create or replace function public.start_prepared_contract_signature(p_kommunikationsvorgang_id bigint,p_expected_revision integer,p_assigned_to uuid)
returns public.kommunikationsvorgang language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.kommunikationsvorgang%rowtype; r record; p_id bigint; v_stichtag date := (now() at time zone 'Europe/Berlin')::date;
begin
 if auth.uid() is null or auth.uid() is distinct from p_assigned_to or not public.is_admin_or_vorstand() then raise exception 'Keine Berechtigung zum Signaturstart' using errcode='42501'; end if;
 select * into v from public.kommunikationsvorgang where id=p_kommunikationsvorgang_id for update;
 if not found or v.vorgangstyp<>'vertrag_signatur' or v.status<>'vorbereitet' or v.revision<>p_expected_revision or v.signatur_gestartet_am is not null or v.signatur_revision is not null or v.zugewiesen_an is distinct from p_assigned_to then raise exception 'Der Vertragsvorgang kann nicht zur Signatur gestartet werden' using errcode='40001'; end if;
 if exists(select 1 from public.prepared_contract_signatur_snapshot_person where kommunikationsvorgang_id=v.id and signatur_revision=v.revision) then raise exception 'Für diese Signaturrevision existiert bereits ein Berechtigungssnapshot' using errcode='23505'; end if;
 for r in select * from public.resolve_vertragsunterzeichner(v_stichtag) loop
   insert into public.prepared_contract_signatur_snapshot_person(kommunikationsvorgang_id,signatur_revision,mitglied_id,unterzeichner_name_snapshot) values(v.id,v.revision,r.mitglied_id,r.unterzeichner_name) on conflict(kommunikationsvorgang_id,signatur_revision,mitglied_id) do update set unterzeichner_name_snapshot=excluded.unterzeichner_name_snapshot returning id into p_id;
   insert into public.prepared_contract_signatur_snapshot_quelle(snapshot_person_id,berechtigungsart,vereinsfunktion_id,vereinsfunktion_bezeichnung_snapshot,vereinsfunktion_besetzung_id,besetzung_gueltig_ab_snapshot,besetzung_gueltig_bis_snapshot,vertretung_id,vertretung_gueltig_ab_snapshot,vertretung_gueltig_bis_snapshot,vertretene_vereinsfunktion_id,vertretene_funktion_bezeichnung_snapshot,vertretene_besetzung_id,vertretene_besetzung_gueltig_ab_snapshot,vertretene_besetzung_gueltig_bis_snapshot) values(p_id,r.berechtigungsart,r.vereinsfunktion_id,r.vereinsfunktion_bezeichnung,r.vereinsfunktion_besetzung_id,r.besetzung_gueltig_ab,r.besetzung_gueltig_bis,r.vertretung_id,r.vertretung_gueltig_ab,r.vertretung_gueltig_bis,r.vertretene_vereinsfunktion_id,r.vertretene_funktion_bezeichnung,r.vertretene_besetzung_id,r.vertretene_besetzung_gueltig_ab,r.vertretene_besetzung_gueltig_bis) on conflict do nothing;
 end loop;
 if (select count(*) from public.prepared_contract_signatur_snapshot_person where kommunikationsvorgang_id=v.id and signatur_revision=v.revision)<2 then raise exception 'Für zwei Vereinsunterschriften sind mindestens zwei unterschiedliche natürliche Personen erforderlich' using errcode='23514'; end if;
 update public.kommunikationsvorgang set status='zur_signatur',signatur_gestartet_am=now(),signatur_revision=revision where id=v.id returning * into v;
 return v;
end; $$;

create or replace function public.prepared_contract_snapshot_unterzeichner(p_kommunikationsvorgang_id bigint,p_signatur_revision integer)
returns table(mitglied_id bigint,unterzeichner_name text,berechtigungsart text,vereinsfunktion_id bigint,vereinsfunktion_bezeichnung text,vereinsfunktion_besetzung_id bigint,vertretung_id bigint,vertretene_vereinsfunktion_id bigint,vertretene_funktion_bezeichnung text,vertretene_besetzung_id bigint)
language sql stable security definer set search_path=public,pg_temp as $$
 select p.mitglied_id,p.unterzeichner_name_snapshot,q.berechtigungsart,q.vereinsfunktion_id,q.vereinsfunktion_bezeichnung_snapshot,q.vereinsfunktion_besetzung_id,q.vertretung_id,q.vertretene_vereinsfunktion_id,q.vertretene_funktion_bezeichnung_snapshot,q.vertretene_besetzung_id
 from public.prepared_contract_signatur_snapshot_person p join lateral (select * from public.prepared_contract_signatur_snapshot_quelle q where q.snapshot_person_id=p.id order by q.id limit 1) q on true
 where p.kommunikationsvorgang_id=p_kommunikationsvorgang_id and p.signatur_revision=p_signatur_revision and public.is_admin_or_vorstand()
 order by p.mitglied_id;
$$;

-- A direct REST transition cannot skip the atomic snapshot RPC.
create or replace function public.guard_prepared_contract_snapshot_start() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if ((tg_op='INSERT' and new.status='zur_signatur') or (tg_op='UPDATE' and old.status='vorbereitet' and new.status='zur_signatur')) and not exists(select 1 from public.prepared_contract_signatur_snapshot_person p where p.kommunikationsvorgang_id=new.id and p.signatur_revision=new.revision) then raise exception 'Signaturstart erfordert einen serverseitigen Berechtigungssnapshot' using errcode='42501'; end if;
 return new;
end; $$;
drop trigger if exists trg_guard_prepared_contract_snapshot_start on public.kommunikationsvorgang;
create trigger trg_guard_prepared_contract_snapshot_start before insert or update of status on public.kommunikationsvorgang for each row execute function public.guard_prepared_contract_snapshot_start();

-- This trigger is a second, non-RPC safety net for the two board positions.
create or replace function public.guard_prepared_contract_board_person_unique() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if new.status='unterschrieben' and new.signatur_schluessel in ('vorstand_1','vorstand_2') and exists(select 1 from public.prepared_contract_signatur p where p.kommunikationsvorgang_id=new.kommunikationsvorgang_id and p.signatur_revision=new.signatur_revision and p.signatur_schluessel in ('vorstand_1','vorstand_2') and p.signatur_schluessel<>new.signatur_schluessel and p.status='unterschrieben' and p.mitglied_id=new.mitglied_id) then raise exception 'Vorstand 1 und Vorstand 2 müssen unterschiedliche natürliche Personen sein' using errcode='23514'; end if;
 return new;
end; $$;
drop trigger if exists trg_guard_prepared_contract_board_person_unique on public.prepared_contract_signatur;
create constraint trigger trg_guard_prepared_contract_board_person_unique after insert or update of status,mitglied_id on public.prepared_contract_signatur deferrable initially immediate for each row execute function public.guard_prepared_contract_board_person_unique();
create unique index ux_prepared_contract_board_person on public.prepared_contract_signatur(kommunikationsvorgang_id,signatur_revision,mitglied_id) where signatur_schluessel in ('vorstand_1','vorstand_2') and mitglied_id is not null;

create or replace function public.speichere_prepared_contract_signatur(
 p_kommunikationsvorgang_id bigint,p_signatur_revision integer,p_signatur_schluessel text,p_mitglied_id bigint,p_unterzeichner_name_snapshot text,p_vereinsfunktion_besetzung_id bigint,p_vertretung_id bigint,p_vertretene_besetzung_id bigint,p_storage_path text,p_signatur_sha256 text,p_unterzeichnet_am timestamptz default now()
) returns public.prepared_contract_signatur language plpgsql security definer set search_path=public,pg_temp as $$
declare v_position public.prepared_contract_signatur%rowtype; v_source record; v_name text; v_other bigint;
begin
 if not public.is_admin_or_vorstand() or auth.uid() is null then raise exception 'Nur angemeldete administrative Vertragsbearbeitung darf Signaturen speichern.' using errcode='42501'; end if;
 if p_signatur_schluessel in ('vorstand_1','vorstand_2') then
   perform 1 from public.prepared_contract_signatur where kommunikationsvorgang_id=p_kommunikationsvorgang_id and signatur_revision=p_signatur_revision and signatur_schluessel in ('vorstand_1','vorstand_2') order by signatur_schluessel for update;
 end if;
 select * into v_position from public.prepared_contract_signatur where kommunikationsvorgang_id=p_kommunikationsvorgang_id and signatur_revision=p_signatur_revision and signatur_schluessel=p_signatur_schluessel for update;
 if not found then raise exception 'Die Signaturposition wurde nicht vorbereitet.' using errcode='P0002'; end if;
 if v_position.status<>'offen' then raise exception 'Die Signaturposition wurde bereits unterschrieben.' using errcode='55000'; end if;
 if p_storage_path !~ ('^'||p_kommunikationsvorgang_id::text||'/'||p_signatur_revision::text||'/[^/]+/[0-9a-fA-F-]{36}[.]png$') or p_signatur_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'Storage-Pfad oder Signatur-Hash ist ungültig.' using errcode='23514'; end if;
 if not exists(select 1 from storage.objects where bucket_id='prepared-contract-signatures' and name=p_storage_path) then raise exception 'Das referenzierte Signaturbild liegt nicht im privaten Storage.' using errcode='23514'; end if;
 if v_position.unterzeichner_typ='vereinsunterzeichner' then
   select q.*,p.mitglied_id,p.unterzeichner_name_snapshot into v_source from public.prepared_contract_signatur_snapshot_person p join public.prepared_contract_signatur_snapshot_quelle q on q.snapshot_person_id=p.id
    where p.kommunikationsvorgang_id=p_kommunikationsvorgang_id and p.signatur_revision=p_signatur_revision and p.mitglied_id=p_mitglied_id and q.vereinsfunktion_besetzung_id is not distinct from p_vereinsfunktion_besetzung_id and q.vertretung_id is not distinct from p_vertretung_id and q.vertretene_besetzung_id is not distinct from p_vertretene_besetzung_id;
   if not found then raise exception 'Die Person oder Berechtigungsquelle gehört nicht zum eingefrorenen Signatur-Snapshot.' using errcode='42501'; end if;
   if p_signatur_schluessel in ('vorstand_1','vorstand_2') then
     select mitglied_id into v_other from public.prepared_contract_signatur where kommunikationsvorgang_id=p_kommunikationsvorgang_id and signatur_revision=p_signatur_revision and signatur_schluessel in ('vorstand_1','vorstand_2') and signatur_schluessel<>p_signatur_schluessel and status='unterschrieben';
     if v_other=p_mitglied_id then raise exception 'Vorstand 1 und Vorstand 2 müssen unterschiedliche natürliche Personen sein.' using errcode='23514'; end if;
   end if;
   update public.prepared_contract_signatur set status='unterschrieben',mitglied_id=v_source.mitglied_id,unterzeichner_name_snapshot=v_source.unterzeichner_name_snapshot,vereinsfunktion_id=v_source.vereinsfunktion_id,vereinsfunktion_bezeichnung_snapshot=v_source.vereinsfunktion_bezeichnung_snapshot,vereinsfunktion_besetzung_id=v_source.vereinsfunktion_besetzung_id,vertretung_id=v_source.vertretung_id,vertretene_vereinsfunktion_id=v_source.vertretene_vereinsfunktion_id,vertretene_funktion_bezeichnung_snapshot=v_source.vertretene_funktion_bezeichnung_snapshot,vertretene_besetzung_id=v_source.vertretene_besetzung_id,storage_bucket='prepared-contract-signatures',storage_path=p_storage_path,signatur_sha256=p_signatur_sha256,unterzeichnet_am=p_unterzeichnet_am,unterzeichnet_von_auth_user_id=auth.uid() where id=v_position.id returning * into v_position;
 else
   select nullif(btrim(concat_ws(' ',vorname,name)),'') into v_name from public.mitglied where id=p_mitglied_id;
   v_name:=coalesce(v_name,nullif(btrim(p_unterzeichner_name_snapshot),'')); if v_name is null then raise exception 'Für die private Unterschrift fehlt ein nachvollziehbarer Personen-Snapshot.' using errcode='23514'; end if;
   update public.prepared_contract_signatur set status='unterschrieben',mitglied_id=p_mitglied_id,unterzeichner_name_snapshot=v_name,storage_bucket='prepared-contract-signatures',storage_path=p_storage_path,signatur_sha256=p_signatur_sha256,unterzeichnet_am=p_unterzeichnet_am,unterzeichnet_von_auth_user_id=auth.uid() where id=v_position.id returning * into v_position;
 end if;
 return v_position;
end; $$;

revoke all on function public.resolve_vertragsunterzeichner(date),public.start_prepared_contract_signature(bigint,integer,uuid),public.prepared_contract_snapshot_unterzeichner(bigint,integer) from public,anon;
grant execute on function public.start_prepared_contract_signature(bigint,integer,uuid),public.prepared_contract_snapshot_unterzeichner(bigint,integer) to authenticated,service_role;
grant execute on function public.resolve_vertragsunterzeichner(date) to service_role;
